rows=['Number of days you will be attending the conference:','Number of people from your organization attending:','Special dietary needs:','Other special needs:']
form='<div class="megagame-form"><h4>MEGAGAME CONFERENCE</h4><h5>Part 1 – Your conference needs:</h5><div class="conference-rows">'+''.join(f'<label><span>{i}.　{escape(label)}</span>{field(str(i),label)}</label>' for i,label in enumerate(rows,1))+'<div class="conference-choice"><span>5.　Will you demonstrate your game? (Tick the option.)<br><small>If No, then go to Part 2. If Yes, then please answer the questions below.</small></span><label>Yes <input type="radio" name="2018-demo" data-note="10-demo-yes" value="yes"></label><label>No <input type="radio" name="2018-demo" data-note="10-demo-no" value="no"></label></div>'+''.join(f'<label><span>{i}.　{escape(label)}</span>{field(str(i),label)}</label>' for i,label in [(6,'Number of demos you want:'),(7,'Number of players in each demo:')])+'</div><h5>Part 2 – Details of your company:</h5><div class="company-name">Name of your company: <em>Griffin Workshop</em></div><label class="long-answer">8.　Write a few sentences about your company (include the following):<ul><li>Why you formed the company</li><li>When you formed the company</li><li>The size of your company</li></ul><textarea data-note="10-company" rows="6" aria-label="Company background"></textarea></label><label class="long-answer">9.　Have you published any games before? (If so please state the name of your game and the type of game.)<textarea data-note="10-games" rows="5" aria-label="Previous published games"></textarea></label></div>'
put(10,'<section class="recreated-page answer-book conference-answer" aria-label="2018 B1 QAB application form"><div class="answer-book-header"><span>HKDSE 2018 · ENGLISH LANGUAGE · PAPER 3 PART B1 · Question-Answer Book</span><strong>B1</strong></div><h3>Task 5: Application form <small>(14 marks)</small></h3>'+bi('Complete the application form below using information from the B1 Data File and your notes.','利用乙部一資料檔和筆記完成以下報名表。')+form+'<p class="answer-end">END OF TASK 5</p></section>')

def writing(n,title,zh,lead,height,key):
 ident=f'2018-b1-{n}-{key}'
 return f'<section class="recreated-page answer-book" aria-label="2018 B1 QAB page {n-9}"><h3>{escape(title)}</h3>'+bi(lead,zh)+f'<label class="answer-field" for="{ident}">{escape(title)}</label><textarea class="answer-box" id="{ident}" data-note="{n}-{key}" data-count-id="{ident}" style="min-height:{height}px" aria-label="{escape(title,quote=True)}"></textarea><p class="answer-count" data-count-for="{ident}">0 words</p>'
put(11,writing(11,'Task 6: Email (18 marks)','利用乙部一資料檔和筆記，寫一封約 120 字的電郵給知名遊戲評論員 Paul Achebe。','Write an email to the well-known board game reviewer Paul Achebe using information from the B1 Data File and your notes. Write around 120 words.',640,'email').replace('<label class="answer-field"','<div class="answer-email-head"><label>Subject: <input data-note="11-subject" aria-label="Email subject"></label></div><label class="answer-field"')+'</section>')
put(12,writing(12,'Task 6: Email, continued','任務 6：電郵續頁。','Continue your email here.',270,'email-cont')+'<p class="answer-end">END OF TASK 6</p><h3>Task 7: Report for company meeting <small>(20 marks)</small></h3>'+bi('Write a report on the questionnaire results and follow-up action for the company meeting using information from the B1 Data File. Write around 150 words.','利用乙部一資料檔，為公司會議撰寫約 150 字的問卷結果和跟進工作報告。')+'<label class="answer-field" for="2018-b1-12-report">Task 7 report</label><textarea class="answer-box" id="2018-b1-12-report" data-note="12-report" data-count-id="2018-b1-12-report" style="min-height:400px" aria-label="Task 7 report"></textarea><p class="answer-count" data-count-for="2018-b1-12-report">0 words</p></section>')
put(13,writing(13,'Task 7: Report, continued','任務 7：報告續頁。','Continue your report here.',700,'report-cont')+'<p class="answer-end">END OF TASK 7<br>END OF PART B1</p></section>')
